/**
 * No workspace or role gating: a profile belongs to the user, not to
 * any one workspace.
 */

import { getTranslations } from "next-intl/server";

import { profile } from "@/lib/profile";
import { ProfileSettingsForm } from "@/components/profile/profile-settings-form";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export default async function ProfileSettingsPage() {
  const t = await getTranslations("profile-settings");
  const user = await profile.getProfile();

  return (
    <div className="space-y-6">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle level={2}>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      <ProfileSettingsForm user={user} />
    </div>
  );
}

"use client";

/**
 * Profile settings form — name editor, read-only email, and an
 * account-deletion danger zone.
 *
 * The delete dialog requires typing DELETE to confirm: deleting an
 * account is irreversible and takes every workspace membership with it.
 *
 * `DELETE_CONFIRMATION` is not translated: the user types the literal
 * "DELETE" in every locale, and only the sentence around it is a
 * message.
 */

import { useState, useTransition, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { updateProfile, deleteAccount } from "@/actions/profile";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

const DELETE_CONFIRMATION = "DELETE";

interface ProfileSettingsFormProps {
  user: {
    name: string | null;
    email: string;
    image?: string | null;
  };
}

function initialFrom(user: ProfileSettingsFormProps["user"]): string {
  const source = user.name || user.email;
  return source.charAt(0).toUpperCase();
}

export function ProfileSettingsForm({ user }: ProfileSettingsFormProps) {
  const t = useTranslations("profile-settings");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [name, setName] = useState(user.name ?? "");
  const [error, setError] = useState<string | null>(null);

  const [deleteOpen, setDeleteOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [isDeleting, setIsDeleting] = useState(false);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);

    startTransition(async () => {
      const result = await updateProfile({ name });
      if (!result.success) {
        setError(result.error);
        return;
      }
      toast.success(t("form.updated"));
      router.refresh();
    });
  }

  function handleDelete() {
    if (confirmText !== DELETE_CONFIRMATION) return;

    setIsDeleting(true);
    startTransition(async () => {
      const result = await deleteAccount();
      if (!result.success) {
        toast.error(result.error);
        setIsDeleting(false);
        return;
      }
      toast.success(t("dangerZone.deleted"));
      router.push("/login");
      router.refresh();
    });
  }

  function resetDeleteDialog(open: boolean) {
    setDeleteOpen(open);
    if (!open) {
      setConfirmText("");
      setIsDeleting(false);
    }
  }

  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle>{t("form.generalTitle")}</CardTitle>
          <CardDescription>{t("form.generalDescription")}</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && <p className="text-sm text-destructive">{error}</p>}

            <div className="flex items-center gap-4">
              <div className="flex size-14 items-center justify-center rounded-full bg-muted text-lg font-semibold text-foreground">
                {initialFrom(user)}
              </div>
              <p className="text-sm text-muted-foreground">
                {t("form.avatarCaption")}
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="name">{t("form.nameLabel")}</Label>
              <Input
                id="name"
                value={name}
                onChange={(event) => setName(event.target.value)}
                disabled={isPending}
                required
                minLength={2}
                maxLength={100}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">{t("form.emailLabel")}</Label>
              <Input id="email" value={user.email} disabled />
              <p className="text-xs text-muted-foreground">
                {t("form.emailNote")}
              </p>
            </div>

            <div className="flex justify-end">
              <Button type="submit" disabled={isPending}>
                {isPending ? t("form.savePending") : t("form.save")}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>

      <Card className="border-destructive/30">
        <CardHeader>
          <CardTitle className="text-destructive">
            {t("dangerZone.title")}
          </CardTitle>
          <CardDescription>{t("dangerZone.description")}</CardDescription>
        </CardHeader>
        <CardContent>
          <Dialog open={deleteOpen} onOpenChange={resetDeleteDialog}>
            <DialogTrigger render={<Button variant="destructive" />}>
              {t("dangerZone.trigger")}
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>{t("dangerZone.dialogTitle")}</DialogTitle>
                <DialogDescription>
                  {t.rich("dangerZone.dialogDescription", {
                    token: () => (
                      <span className="font-mono font-semibold">
                        {DELETE_CONFIRMATION}
                      </span>
                    ),
                  })}
                </DialogDescription>
              </DialogHeader>

              <div className="space-y-2">
                <Label htmlFor="confirm-delete" className="sr-only">
                  {t("dangerZone.confirmLabel", {
                    token: DELETE_CONFIRMATION,
                  })}
                </Label>
                <Input
                  id="confirm-delete"
                  value={confirmText}
                  onChange={(event) => setConfirmText(event.target.value)}
                  placeholder={DELETE_CONFIRMATION}
                  disabled={isDeleting}
                  autoComplete="off"
                />
              </div>

              <DialogFooter>
                <Button
                  variant="outline"
                  onClick={() => resetDeleteDialog(false)}
                  disabled={isDeleting}
                >
                  {t("dangerZone.cancel")}
                </Button>
                <Button
                  variant="destructive"
                  onClick={handleDelete}
                  disabled={isDeleting || confirmText !== DELETE_CONFIRMATION}
                >
                  {isDeleting
                    ? t("dangerZone.confirmPending")
                    : t("dangerZone.confirm")}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </CardContent>
      </Card>
    </>
  );
}

"use server";

/**
 * Profile settings server actions — thin transport over the bound
 * profile service (`@/lib/profile`): parse input with the schema from
 * `@intelligo-dev/auth`, call the service, map any `ProfileServiceError` to
 * a friendly message, and revalidate. No business rules here — those
 * live in the service.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import {
  isProfileServiceError,
  updateProfileSchema,
  type UpdateProfileInput,
} from "@intelligo-dev/auth";

import { profile } from "@/lib/profile";

export type ProfileActionResult<T = undefined> =
  { success: true; data: T } | { success: false; error: string };

type Translator = Awaited<
  ReturnType<typeof getTranslations<"profile-settings">>
>;

function friendlyMessage(t: Translator): Partial<Record<string, string>> {
  return {
    forbidden: t("errors.forbidden"),
    provider_error: t("errors.providerError"),
  };
}

function friendlyError(error: unknown, t: Translator): string {
  if (isProfileServiceError(error)) {
    return friendlyMessage(t)[error.code] ?? error.message;
  }
  return error instanceof Error
    ? error.message
    : t("errors.somethingWentWrong");
}

export async function updateProfile(
  input: UpdateProfileInput
): Promise<ProfileActionResult> {
  const t = await getTranslations("profile-settings");
  const parsed = updateProfileSchema.safeParse(input);
  if (!parsed.success) {
    return {
      success: false,
      error: parsed.error.issues[0]?.message ?? t("errors.invalidInput"),
    };
  }

  try {
    await profile.updateProfile(parsed.data);
    revalidatePath("/settings/profile");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

export async function deleteAccount(): Promise<ProfileActionResult> {
  const t = await getTranslations("profile-settings");
  try {
    await profile.deleteAccount();
    revalidatePath("/", "layout");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

import "server-only";

/**
 * Binds the profile service (`@intelligo-dev/auth`) with an
 * account-deletion confirmation email sent through `sendEmail`
 * (`@intelligo-dev/core/email`). `sendEmail` never throws and the
 * service treats `onAccountDeleted` as fire-and-forget, so no error
 * handling is needed. Drop the binding to send no email.
 */

import { getTranslations } from "next-intl/server";

import { createProfileService } from "@intelligo-dev/auth";
import { sendEmail } from "@intelligo-dev/core/email";

export const profile = createProfileService({
  onAccountDeleted: async ({ email }) => {
    const t = await getTranslations("profile-settings");
    await sendEmail({
      to: email,
      subject: t("email.subject"),
      html: `
        <h2>${t("email.heading")}</h2>
        <p>${t("email.body", { email })}</p>
        <p>${t("email.warning")}</p>
      `,
    });
  },
});

"use client";

/**
 * Error boundary for profile settings. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="settings-profile" />;
}
